left = {0,1,2,3}
right = {4,5,6,7}
edges = []
for u in left:
    for v in right:
        if u < v:
            edges.append((u,v))
        else:
            edges.append((v,u))
edges.sort()
print("Edges:", edges)
print("Count:", len(edges))
# Verify degrees
deg = [0]*8
for u,v in edges:
    deg[u] += 1
    deg[v] += 1
print("Degrees:", deg)
# Check fixed edges present
fixed = [(0,4), (0,7), (2,4)]
for e in fixed:
    assert e in edges or (e[1],e[0]) in edges, f"Missing {e}"
print("All fixed edges present")
# Check no triangles
tri = 0
for i in range(8):
    for j in range(i+1,8):
        for k in range(j+1,8):
            if (i,j) in edges and (i,k) in edges and (j,k) in edges:
                tri += 1
print("Triangles:", tri)
# Check girth: shortest cycle length
# We can compute via BFS
from collections import deque
def shortest_cycle():
    best = float('inf')
    for s in range(8):
        parent = [-1]*8
        dist = [-1]*8
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in range(8):
                if (u,v) in edges or (v,u) in edges:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        q.append(v)
                    elif parent[u] != v and parent[v] != u:
                        # found cycle
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < best:
                            best = cycle_len
        # also check self loops? none
    return best
print("Shortest cycle:", shortest_cycle())
